"use client";

import { Suspense, type ReactNode } from "react";
import { useDataGridUrlState, type UseDataGridUrlStateOptions } from "./use-data-grid-url-state";

/** Public entry point — the only module consumers/docs should import from. */
export {
  useDataGridUrlState,
  type UseDataGridUrlStateOptions,
  type UseDataGridUrlStateResult,
} from "./use-data-grid-url-state";
export type { UrlLayoutPart } from "./layout-param";
export {
  useDataGridUrlPagination,
  type UseDataGridUrlPaginationOptions,
  type UseDataGridUrlPaginationResult,
} from "./use-data-grid-url-pagination";

/** Props for {@link DataGridUrlState}. */
export type DataGridUrlStateProps = UseDataGridUrlStateOptions;

/**
 * Renders nothing; syncs the grid's sort/filter/search state with the URL (see
 * {@link useDataGridUrlState}). Mount it once inside `<DataGridProvider>`, alongside
 * `<DataGridRoot>`/`<DataGridToolbar>`. Requires a nuqs adapter (`NuqsAdapter` from
 * `nuqs/adapters/react`, or your framework's) somewhere above it in the tree. It reads the URL
 * under its own `<Suspense>` boundary, so a statically prerendered page needs none for it.
 *
 * @example
 * <DataGridProvider data={rows} columns={columns} getRowId={(r) => r.id}>
 *   <DataGridUrlState prefix="orders" />
 *   <DataGridToolbar><DataGridSearch /></DataGridToolbar>
 *   <DataGridRoot>...</DataGridRoot>
 * </DataGridProvider>
 */
export function DataGridUrlState(props: DataGridUrlStateProps): ReactNode {
  return (
    <Suspense fallback={null}>
      <UrlStateSync {...props} />
    </Suspense>
  );
}

function UrlStateSync(props: DataGridUrlStateProps): ReactNode {
  useDataGridUrlState(props);
  return null;
}

import type { BuiltInFilterOperator } from "@/registry/default/components/data-grid/data-grid";

/** The closed set of built-in {@link BuiltInFilterOperator} values, for validating URL input against. */
export const FILTER_OPERATORS: ReadonlySet<BuiltInFilterOperator> = new Set([
  "contains",
  "notContains",
  "equals",
  "notEquals",
  "startsWith",
  "endsWith",
  "empty",
  "notEmpty",
  "gt",
  "gte",
  "lt",
  "lte",
  "isBetween",
  "isAnyOf",
  "isNoneOf",
] satisfies BuiltInFilterOperator[]);

/** Narrows an untrusted (URL-decoded) string to {@link BuiltInFilterOperator}. */
export function isFilterOperator(value: string): value is BuiltInFilterOperator {
  return FILTER_OPERATORS.has(value as BuiltInFilterOperator);
}

import type { FilterGroup, FilterNode, FilterOperatorInput, FilterSpec } from "@/registry/default/components/data-grid/data-grid";
import { MAX_FILTER_GROUP_DEPTH, filterOperatorInput, groupChildren, isFilterGroup } from "@/registry/default/components/data-grid/data-grid-sdk";
import { isFilterOperator } from "./filter-operators";
import { safeDecode } from "./sort-param";

/** In-value separator for `isBetween`'s two-part value. `encodeURIComponent` leaves `~` in its unreserved set untouched, so a literal `~` inside a bound must be escaped separately (see {@link encodeRangePart}) to stay unambiguous against the separator. */
const RANGE_SEPARATOR = "~";

/** In-value separator for the `isAnyOf` and `isNoneOf` choice lists. `encodeURIComponent` escapes a literal `|` inside a choice to `%7C`, so the raw separator can never collide with a choice's own characters. */
const ANYOF_SEPARATOR = "|";

/** Token for an empty list entry (the "(Blanks)" value). `encodeURIComponent` never emits a lone `%`, so no encoded value collides with it, and a sole empty entry stays distinct from an empty list. */
const EMPTY_ENTRY_TOKEN = "%";

/** A hand-edited URL must not express an unbounded view state; filter segments beyond the cap are dropped. */
const MAX_URL_FILTERS = 64;

/** Groups kept from a URL; the `[` and `]` segments are bounded separately from the leaf rows. */
const MAX_URL_FILTER_GROUPS = 16;

/** Raw comma-separated segments read before parsing stops; bounds the work a URL of empty segments can cost. */
const MAX_URL_FILTER_SEGMENTS = MAX_URL_FILTERS * 4;

const GROUP_CLOSE = "]";

/** Longest decoded filter value (or choice, or range bound) a URL may carry; a segment above it is dropped, never cut, so a link cannot mean another filter. */
const MAX_URL_FILTER_VALUE_LENGTH = 1000;

/** Bound for one `isAnyOf` or `isNoneOf` list parsed from a URL when the caller names no per-column limit. */
const DEFAULT_MAX_ANYOF_CHOICES = 1000;

/** Options for {@link parseFilterState}. */
export type ParseFilterStateOptions = {
  /** Most entries an `isAnyOf` or `isNoneOf` list of this column may hold, usually its number of `choices`. Returns `undefined` for the 1000 default. */
  maxChoices?: (columnId: string) => number | undefined;
  /** The value shape of a custom operator registered on the column, or `undefined` when the column does not register it; a segment with an unregistered operator is dropped. */
  operatorInput?: (columnId: string, operator: string) => FilterOperatorInput | undefined;
  /** The lowercased values an `isAnyOf` or `isNoneOf` list of the column may keep, or `undefined` to check nothing. An entry whose lowercased text is outside the set is dropped; the blank entry stays. */
  choiceValues?: (columnId: string) => ReadonlySet<string> | undefined;
  /** Receives the number of list entries dropped for falling outside {@link ParseFilterStateOptions.choiceValues}. */
  onUnknownChoices?: (columnId: string, count: number) => void;
};

/** Options for {@link serializeFilterState}. */
export type SerializeFilterStateOptions = Pick<ParseFilterStateOptions, "operatorInput" | "maxChoices">;

/** The entries of a set filter list that `choiceValues` allows, compared without case as `isAnyOf` matches; `null` when none of a non-empty list is left. */
function knownChoices(columnId: string, operator: string, value: FilterSpec["value"], options: ParseFilterStateOptions): FilterSpec["value"] | null {
  const allowed = (operator === "isAnyOf" || operator === "isNoneOf") && Array.isArray(value) ? options.choiceValues?.(columnId) : undefined;
  if (!allowed || !Array.isArray(value)) return value;
  const kept = value.filter((entry) => entry === "" || allowed.has(entry.toLowerCase()));
  if (kept.length === value.length) return value;
  options.onUnknownChoices?.(columnId, value.length - kept.length);
  return kept.length === 0 ? null : kept;
}

/** `encodeURIComponent` plus escaping the one character it doesn't (`~`), so a literal tilde in a bound never collides with {@link RANGE_SEPARATOR}. */
function encodeRangePart(part: string): string {
  return encodeURIComponent(part).replace(/~/g, "%7E");
}

function encodeFilterValue(input: FilterOperatorInput, value: FilterSpec["value"]): string {
  if (value === undefined) return "";
  if (Array.isArray(value) && input === "range") return `${encodeRangePart(value[0])}${RANGE_SEPARATOR}${encodeRangePart(value[1])}`;
  if (Array.isArray(value)) return value.map((entry) => (entry === "" ? EMPTY_ENTRY_TOKEN : encodeURIComponent(entry))).join(ANYOF_SEPARATOR);
  return encodeURIComponent(value);
}

/**
 * Compact URL encoding for a {@link FilterNode}[]: comma-separated `columnId:operator:value` triples
 * (`value` omitted for operators with none, e.g. `empty`/`notEmpty`), column id and value
 * percent-encoded. `isBetween`'s two-value range encodes as `min~max`, the `isAnyOf` and `isNoneOf` choice lists as
 * `a|b|c` (each choice percent-encoded, so the raw `|` separator can never collide) — both still
 * one `value` field, so every other operator's format — and any URL generated before those
 * operators existed — round-trips unchanged. An empty list entry encodes as the lone token `%`
 * (`a|%`), so `[""]` differs from `[]`; a part left empty by hand-editing still reads as an empty entry. `filterId` is never serialized — it's a transient
 * list-rendering identity the store re-derives on parse, not part of the filter's meaning.
 * A {@link FilterGroup} is an open segment `[or` or `[and`, its children, and a closing `]` segment;
 * `encodeURIComponent` escapes `[` and `]`, so no id or value can imitate one. A group nests one more
 * group at most; deeper and empty groups are not written.
 *
 * @example serializeFilterState([{ columnId: "age", operator: "gt", value: "30" }])
 * // => "age:gt:30"
 * @example serializeFilterState([{ columnId: "name", operator: "empty" }])
 * // => "name:empty:"
 * @example serializeFilterState([{ columnId: "age", operator: "isBetween", value: ["10", "30"] }])
 * // => "age:isBetween:10~30"
 * @example serializeFilterState([{ columnId: "status", operator: "isAnyOf", value: ["new", "open"] }])
 * // => "status:isAnyOf:new|open"
 * @example serializeFilterState([{ join: "or", filters: [{ columnId: "a", operator: "equals", value: "1" }] }])
 * // => "[or,a:equals:1,]"
 * @example serializeFilterState([{ join: "and", not: true, filters: [{ columnId: "a", operator: "equals", value: "1" }] }])
 * // => "[notand,a:equals:1,]"
 */
export function serializeFilterState(filters: readonly FilterNode[], options: SerializeFilterStateOptions = {}): string {
  const segments: string[] = [];
  writeNodes(filters, 0, segments, options, false);
  return segments.join(",");
}

/** Returns true when it skipped a node the reader would not keep. */
function writeNodes(nodes: readonly FilterNode[], depth: number, segments: string[], options: SerializeFilterStateOptions, negated: boolean): boolean {
  let lost = false;
  for (const node of nodes) {
    if (!isFilterGroup(node)) {
      const input = isFilterOperator(node.operator) ? filterOperatorInput(node.operator) : (options.operatorInput?.(node.columnId, node.operator) ?? "single");
      if (!readerKeeps(node, options, negated)) {
        lost = true;
        continue;
      }
      segments.push(`${encodeURIComponent(node.columnId)}:${encodeURIComponent(node.operator)}:${encodeFilterValue(input, node.value)}`);
      continue;
    }
    const children = groupChildren(node);
    if (depth >= MAX_FILTER_GROUP_DEPTH || children.length === 0) {
      lost = true;
      continue;
    }
    const start = segments.length;
    const own = node.not === true;
    segments.push(`[${own ? "not" : ""}${node.join === "or" ? "or" : "and"}`);
    const childLost = writeNodes(children, depth + 1, segments, options, negated || own);
    if (childLost) lost = true;
    // a negated group missing a term would match other rows, so it is not written
    if (segments.length === start + 1 || (own && childLost)) segments.length = start;
    else segments.push(GROUP_CLOSE);
  }
  return lost;
}

function valueStrings(value: FilterSpec["value"]): readonly string[] {
  if (Array.isArray(value)) return value;
  return typeof value === "string" ? [value] : [];
}

/** True unless {@link parseFilterState} would drop the leaf. An `isAnyOf` list over its bound stays and the reader cuts it. */
function readerKeeps(node: FilterSpec, options: SerializeFilterStateOptions, negated: boolean): boolean {
  if (valueStrings(node.value).some((part) => part.length > MAX_URL_FILTER_VALUE_LENGTH)) return false;
  if ((node.operator !== "isNoneOf" && !(negated && node.operator === "isAnyOf")) || !Array.isArray(node.value)) return true;
  return node.value.length <= (options.maxChoices?.(node.columnId) ?? DEFAULT_MAX_ANYOF_CHOICES);
}

/** Sentinel distinguishing "decode failed, drop the segment" from a legitimately-empty decoded value (`""`). */
const DECODE_FAILED = Symbol("decode-failed");

/** Decodes a segment's value part per `operator`: `isBetween` splits on {@link RANGE_SEPARATOR} into a tuple, `isAnyOf` and `isNoneOf` split on {@link ANYOF_SEPARATOR} into a choice list (empty value = empty list), everything else stays a plain string. Malformed input (wrong tuple arity, bad percent-encoding) returns {@link DECODE_FAILED}. */
function decodeFilterValue(operator: string, input: FilterOperatorInput, raw: string, maxChoices: number, negated: boolean): FilterSpec["value"] | typeof DECODE_FAILED {
  if (input === "list") {
    if (raw === "") return [];
    const parts: string[] = [];
    // one entry past the bound tells an over-long list from an exact fit without splitting the whole value
    for (const rawPart of raw.split(ANYOF_SEPARATOR, maxChoices + 1)) {
      if (parts.length >= maxChoices) {
        // a truncated exclusion list would match more rows than the link meant
        if (operator === "isNoneOf" || negated) return DECODE_FAILED;
        break;
      }
      const decoded = rawPart === EMPTY_ENTRY_TOKEN ? "" : safeDecode(rawPart);
      if (decoded === null || decoded.length > MAX_URL_FILTER_VALUE_LENGTH) return DECODE_FAILED;
      parts.push(decoded);
    }
    return parts;
  }
  if (input !== "range") {
    const decoded = safeDecode(raw);
    return decoded === null || decoded.length > MAX_URL_FILTER_VALUE_LENGTH ? DECODE_FAILED : decoded;
  }
  const parts = raw.split(RANGE_SEPARATOR);
  if (parts.length !== 2) return DECODE_FAILED;
  const [min, max] = parts.map(safeDecode);
  if (min == null || max == null || min.length > MAX_URL_FILTER_VALUE_LENGTH || max.length > MAX_URL_FILTER_VALUE_LENGTH) return DECODE_FAILED;
  return [min, max];
}

/**
 * Inverse of {@link serializeFilterState}. Malformed segments (unknown operator, empty/undecodable
 * column id, wrong field count, malformed `isBetween` range or `isAnyOf` / `isNoneOf` list) are dropped silently
 * rather than throwing — a corrupt/hand-edited URL degrades to fewer filters, never an error.
 * Parsing stops after 256 raw segments. The parsed tree is capped at 64 filter rows and 16 groups, and each `isAnyOf`
 * list at `options.maxChoices(columnId)` entries (1000 by default), and keeps only the list entries `options.choiceValues` allows; a segment whose decoded value, choice, or range bound
 * exceeds 1,000 characters is dropped; the first segments win, so a
 * hand-edited URL cannot express an unbounded filter set. A group opener deeper than the nesting cap,
 * with an unknown join, or over the group cap drops its whole subtree; a stray `]` is ignored, an
 * unclosed group closes at the end, and an empty group is dropped. An `isNoneOf` list over its bound drops
 * the whole segment. A negated group (`[notand`, `[notor`) that loses a child or is left unclosed is dropped whole.
 * Every filter parses without a `filterId`; the store backfills a fresh stable one on the next sync.
 *
 * @example parseFilterState("age:gt:30") // => [{ columnId: "age", operator: "gt", value: "30" }]
 * @example parseFilterState("name:empty:") // => [{ columnId: "name", operator: "empty", value: "" }]
 * @example parseFilterState("age:isBetween:10~30") // => [{ columnId: "age", operator: "isBetween", value: ["10", "30"] }]
 * @example parseFilterState("status:isAnyOf:new|open") // => [{ columnId: "status", operator: "isAnyOf", value: ["new", "open"] }]
 * @example parseFilterState("garbage") // => []
 */
export function parseFilterState(raw: string, options: ParseFilterStateOptions = {}): FilterNode[] {
  if (!raw) return [];
  type Frame = { join: FilterGroup["join"]; not: boolean; filters: FilterNode[]; dropped: boolean; lostChild: boolean };
  const root: Frame = { join: "and", not: false, filters: [], dropped: false, lostChild: false };
  const stack: Frame[] = [root];
  let leaves = 0;
  let groups = 0;
  const loseChild = () => stack.forEach((frame) => (frame.lostChild = true));
  const closeTop = (closed: boolean) => {
    const frame = stack.pop()!;
    // a negated group missing a term would match different rows, so it goes whole
    if (frame.dropped || frame.filters.length === 0 || (frame.not && (frame.lostChild || !closed))) return loseChild();
    stack[stack.length - 1]!.filters.push(frame.not ? { join: frame.join, not: true, filters: frame.filters } : { join: frame.join, filters: frame.filters });
  };
  let start = 0;
  for (let read = 0; read < MAX_URL_FILTER_SEGMENTS && start <= raw.length && leaves < MAX_URL_FILTERS; read++) {
    const comma = raw.indexOf(",", start);
    const end = comma === -1 ? raw.length : comma;
    const segment = raw.slice(start, end);
    start = end + 1;
    if (segment === GROUP_CLOSE) {
      if (stack.length > 1) closeTop(true);
      continue;
    }
    if (segment.startsWith("[")) {
      const join = segment === "[or" || segment === "[notor" ? "or" : segment === "[and" || segment === "[notand" ? "and" : undefined;
      const parent = stack[stack.length - 1]!;
      const dropped = parent.dropped || join === undefined || stack.length > MAX_FILTER_GROUP_DEPTH || groups >= MAX_URL_FILTER_GROUPS;
      if (!dropped) groups++;
      stack.push({ join: join ?? "and", not: segment.startsWith("[not"), filters: [], dropped, lostChild: false });
      continue;
    }
    const parts = segment.split(":");
    if (parts.length !== 3) { loseChild(); continue; }
    const [columnId, operator, rawValue] = parts;
    if (!columnId || operator === undefined || rawValue === undefined) { loseChild(); continue; }
    const decodedId = safeDecode(columnId);
    const decodedOperator = safeDecode(operator);
    if (decodedId === null || decodedId === "" || decodedOperator === null) { loseChild(); continue; }
    const input = isFilterOperator(decodedOperator) ? filterOperatorInput(decodedOperator) : options.operatorInput?.(decodedId, decodedOperator);
    if (input === undefined) { loseChild(); continue; }
    const value = decodeFilterValue(decodedOperator, input, rawValue, options.maxChoices?.(decodedId) ?? DEFAULT_MAX_ANYOF_CHOICES, stack.some((open) => open.not));
    if (value === DECODE_FAILED) { loseChild(); continue; }
    const frame = stack[stack.length - 1]!;
    if (frame.dropped) { loseChild(); continue; }
    const known = knownChoices(decodedId, decodedOperator, value, options);
    if (known === null) { loseChild(); continue; }
    frame.filters.push({ columnId: decodedId, operator: decodedOperator, value: known });
    leaves++;
  }
  while (stack.length > 1) closeTop(false);
  return root.filters;
}

import type { FilterJoinOperator } from "@/registry/default/components/data-grid/data-grid";

/** Reads a legacy `join` URL param. Only exactly `"or"` means `"or"`; an absent, empty, or malformed value is `"and"`. */
export function parseLegacyJoin(raw: string): FilterJoinOperator {
  return raw === "or" ? "or" : "and";
}

import type { ColumnLayout } from "@/registry/default/components/data-grid/data-grid";
import { safeDecode } from "./sort-param";

/** The parts of a {@link ColumnLayout} the URL can carry. */
export type UrlLayoutPart = "order" | "hidden" | "widths" | "pins";

/** Segments read from one layout param; a forged link cannot allocate past it. */
export const MAX_URL_LAYOUT_COLUMNS = 1024;

/** A layout param longer than this is ignored as a whole. */
export const MAX_URL_LAYOUT_PARAM_LENGTH = 16_384;

const NONE = "-";
const WIDTH_PATTERN = /^\d{1,5}$/;

function encodeId(id: string): string {
  return id === NONE ? "%2D" : encodeURIComponent(id);
}

function serializePair(id: string, value: string | number): string {
  return `${encodeId(id)}:${value}`;
}

/**
 * Compact URL encoding of one {@link ColumnLayout} part: `order` and `hidden` are comma-separated
 * column ids, `widths` is `id:px` pairs, `pins` is `id:s` / `id:e` pairs (start / end; the legacy
 * `l` / `r` codes are read, not written). Ids are percent-encoded.
 * An empty `hidden` or `pins` part is written as `-`.
 *
 * @example serializeLayoutPart("widths", { ...layout, widths: { name: 240 } }) // => "name:240"
 */
export function serializeLayoutPart(part: UrlLayoutPart, layout: ColumnLayout): string {
  switch (part) {
    case "order":
      return layout.order.map(encodeId).join(",");
    case "hidden":
      return layout.hidden.length === 0 ? NONE : layout.hidden.map(encodeId).join(",");
    case "widths":
      return Object.entries(layout.widths)
        .map(([id, width]) => serializePair(id, Math.round(width)))
        .join(",");
    case "pins": {
      const pins = Object.entries(layout.pins);
      return pins.length === 0 ? NONE : pins.map(([id, side]) => serializePair(id, side === "start" ? "s" : "e")).join(",");
    }
    default:
      return "";
  }
}

function decodeId(raw: string): string | null {
  const id = raw === "" ? null : safeDecode(raw);
  return id === "" ? null : id;
}

function parseIds(raw: string): string[] {
  const seen = new Set<string>();
  for (const segment of raw.split(",", MAX_URL_LAYOUT_COLUMNS)) {
    const id = decodeId(segment);
    if (id !== null) seen.add(id);
  }
  return [...seen];
}

function parsePairs<V>(raw: string, parseValue: (value: string) => V | null): [string, V][] {
  const seen = new Set<string>();
  const pairs: [string, V][] = [];
  for (const segment of raw.split(",", MAX_URL_LAYOUT_COLUMNS)) {
    const colon = segment.indexOf(":");
    if (colon < 0 || segment.indexOf(":", colon + 1) >= 0) continue;
    const id = decodeId(segment.slice(0, colon));
    if (id === null || seen.has(id)) continue;
    const value = parseValue(segment.slice(colon + 1));
    if (value === null) continue;
    seen.add(id);
    pairs.push([id, value]);
  }
  return pairs;
}

/**
 * Inverse of {@link serializeLayoutPart}. Returns only the given part: `{}` when the param is
 * empty or longer than {@link MAX_URL_LAYOUT_PARAM_LENGTH}, an empty part (such as `{ order: [] }`)
 * when it holds nothing valid. Reads at most
 * {@link MAX_URL_LAYOUT_COLUMNS} segments; undecodable, empty, and repeated ids and malformed values
 * are dropped (the first segment of an id wins). Never throws.
 *
 * @example parseLayoutPart("pins", "name:s,age:e") // => { pins: { name: "start", age: "end" } }
 */
export function parseLayoutPart(part: UrlLayoutPart, raw: string): Partial<ColumnLayout> {
  if (raw === "" || raw.length > MAX_URL_LAYOUT_PARAM_LENGTH) return {};
  switch (part) {
    case "order":
      return { order: parseIds(raw) };
    case "hidden":
      return { hidden: raw === NONE ? [] : parseIds(raw) };
    case "widths":
      return { widths: Object.fromEntries(parsePairs(raw, (v) => (WIDTH_PATTERN.test(v) ? Number(v) : null))) };
    case "pins":
      return {
        pins: Object.fromEntries(parsePairs(raw, (v) => (v === "l" || v === "s" ? "start" : v === "r" || v === "e" ? "end" : null))) as ColumnLayout["pins"],
      };
    default:
      return {};
  }
}

/** Absolute ceiling for the URL `page` param: a page number beyond it is a typo or an attack, and parses as 1 like any other invalid value. */
export const MAX_URL_PAGE = 1_000_000;

/**
 * URL encoding for the 1-based `page` number: the plain decimal string, omitted entirely when
 * `page` is 1 (the default), matching `join`'s omit-at-default convention.
 *
 * @example serializePage(1) // => "" (the default; omitted from the URL)
 * @example serializePage(3) // => "3"
 */
export function serializePage(page: number): string {
  return page <= 1 ? "" : String(page);
}

/**
 * Inverse of {@link serializePage}. Anything that isn't a positive integer (absent, empty,
 * negative, fractional, hand-edited garbage) parses as `1` — never throws.
 *
 * @example parsePage("3") // => 3
 * @example parsePage("") // => 1
 * @example parsePage("garbage") // => 1
 */
export function parsePage(raw: string): number {
  const n = Number(raw);
  return raw !== "" && Number.isInteger(n) && n >= 1 && n <= MAX_URL_PAGE ? n : 1;
}

/**
 * URL encoding for `pageSize`: the plain decimal string, omitted when it equals `defaultPageSize`.
 *
 * @example serializePageSize(25, 25) // => "" (matches the default; omitted from the URL)
 * @example serializePageSize(50, 25) // => "50"
 */
export function serializePageSize(pageSize: number, defaultPageSize: number): string {
  return pageSize === defaultPageSize ? "" : String(pageSize);
}

/**
 * Inverse of {@link serializePageSize}. Falls back to `defaultPageSize` for anything that isn't a
 * positive integer. When `allowedSizes` is given, a parsed value outside that list also falls back
 * to `defaultPageSize` — the URL cannot force a page size the consumer didn't offer.
 *
 * @example parsePageSize("50", 25) // => 50
 * @example parsePageSize("", 25) // => 25
 * @example parsePageSize("999", 25, [10, 25, 50]) // => 25 (not in the allowed list)
 */
export function parsePageSize(raw: string, defaultPageSize: number, allowedSizes?: readonly number[]): number {
  const n = Number(raw);
  if (raw === "" || !Number.isInteger(n) || n < 1) return defaultPageSize;
  if (allowedSizes && !allowedSizes.includes(n)) return defaultPageSize;
  return n;
}

import { MAX_GROUP_LEVELS } from "@/registry/default/components/data-grid/data-grid-sdk";
import { safeDecode } from "./sort-param";

/** Comma-separated column ids, outermost group first, each percent-encoded (ids may contain `,`). */
export function serializeGroupBy(groupBy: readonly string[]): string {
  return groupBy.map(encodeURIComponent).join(",");
}

/**
 * Inverse of {@link serializeGroupBy}. Reads at most the first 4 raw segments; an empty or
 * undecodable segment and a repeated id drop. Column checks belong to the caller.
 *
 * @example parseGroupBy("region,team") // => ["region", "team"]
 */
export function parseGroupBy(raw: string): string[] {
  const ids: string[] = [];
  for (const segment of raw.split(",", MAX_GROUP_LEVELS)) {
    const id = safeDecode(segment);
    if (id && !ids.includes(id)) ids.push(id);
  }
  return ids;
}

import { useEffect, useRef } from "react";
import { isDev } from "@/registry/default/components/data-grid/data-grid-sdk";

/** Namespaces a URL param key for multi-grid pages, e.g. `prefixedKey("orders", "sort")` => `"orders_sort"`. */
export function prefixedKey(prefix: string | undefined, key: string): string {
  return prefix ? `${prefix}_${key}` : key;
}

const mountedByScope = new Map<string, number>();

/** Warns once in development when a second mounted hook of the same kind uses the prefix: each instance applies the URL once on mount, so two grids on one key never stay linked. */
export function useWarnSharedPrefix(hook: "useDataGridUrlState" | "useDataGridUrlPagination", prefix: string | undefined): void {
  const warned = useRef(false);
  useEffect(() => {
    const scope = `${hook}:${prefix ?? ""}`;
    const others = mountedByScope.get(scope) ?? 0;
    mountedByScope.set(scope, others + 1);
    if (others > 0 && !warned.current && isDev()) {
      warned.current = true;
      console.warn(`[data-grid-url-state] two ${hook} instances use ${prefix ? `the prefix "${prefix}"` : "no prefix"}; give each grid its own prefix`);
    }
    return () => {
      const left = (mountedByScope.get(scope) as number) - 1;
      if (left > 0) mountedByScope.set(scope, left);
      else mountedByScope.delete(scope);
    };
  }, [hook, prefix]);
}

import type { SortSpec } from "@/registry/default/components/data-grid/data-grid";
import { MAX_SPEC_SORTS } from "@/registry/default/components/data-grid/data-grid-sdk";

/** A hand-edited URL must not express an unbounded sort list; segments beyond the cap are dropped. */
/** Raw segments read from the param, so a forged link of millions of commas allocates nothing past this. */
const MAX_URL_SORT_SEGMENTS = 256;

/**
 * Compact URL encoding for {@link SortSpec}[]: comma-separated `columnId:direction` pairs,
 * column id percent-encoded (ids are consumer-controlled and may contain `,`/`:`).
 *
 * @example serializeSortState([{ columnId: "name", direction: "asc" }, { columnId: "age", direction: "desc" }])
 * // => "name:asc,age:desc"
 */
export function serializeSortState(sorts: readonly SortSpec[]): string {
  return sorts.map((s) => `${encodeURIComponent(s.columnId)}:${s.direction}`).join(",");
}

/** `decodeURIComponent` throws on malformed `%` sequences a hand-edited URL can contain — never let that surface. */
export function safeDecode(value: string): string | null {
  try {
    return decodeURIComponent(value);
  } catch {
    return null;
  }
}

/**
 * Inverse of {@link serializeSortState}. Malformed segments (missing direction, bad direction
 * value, empty/undecodable column id) are dropped silently rather than throwing — a corrupt/hand-edited
 * URL degrades to fewer sorts, never an error. A column id repeated in the URL yields one sort entry
 * (the first segment wins), matching the grid's one-direction-per-column sort model. The parsed
 * list is capped at 64 sorts.
 *
 * @example parseSortState("name:asc,age:desc") // => [{ columnId: "name", direction: "asc" }, { columnId: "age", direction: "desc" }]
 * @example parseSortState("garbage") // => []
 */
export function parseSortState(raw: string): SortSpec[] {
  if (!raw) return [];
  const sorts: SortSpec[] = [];
  // one sort entry per column (the grid's sort model) — a repeated column id keeps its first segment
  const seenColumns = new Set<string>();
  for (const segment of raw.split(",", MAX_URL_SORT_SEGMENTS)) {
    if (sorts.length >= MAX_SPEC_SORTS) break;
    const [columnId, direction] = segment.split(":");
    if (!columnId || (direction !== "asc" && direction !== "desc")) continue;
    const decoded = safeDecode(columnId);
    if (decoded === null || decoded === "") continue;
    if (seenColumns.has(decoded)) continue;
    seenColumns.add(decoded);
    sorts.push({ columnId: decoded, direction });
  }
  return sorts;
}

"use client";

import { useCallback, useMemo } from "react";
import { useQueryState } from "nuqs";
import { DEFAULT_PAGE_SIZES } from "@/registry/default/components/data-grid-pagination/pagination-math";
import { parsePage, parsePageSize, serializePage, serializePageSize } from "./page-param";
import { prefixedKey, useWarnSharedPrefix } from "./prefixed-key";

/** Options for {@link useDataGridUrlPagination}. */
export type UseDataGridUrlPaginationOptions = {
  /** Namespaces the `page`/`pageSize` URL keys as `<prefix>_<key>`, so multiple grids can coexist on one page. */
  prefix?: string;
  /** `pageSize` this many is omitted from the URL. Also the fallback for an invalid URL value. Default: the first of `pageSizeOptions` (10 with the default list). */
  defaultPageSize?: number;
  /** A `pageSize` URL value outside this list (default: the pager sizes 10, 25, 50, 100) falls back to `defaultPageSize`. */
  pageSizeOptions?: readonly number[];
};

/** The controlled pair: spread it onto `DataGridProvider` (a grid that pages its view) or into `useDataGridServerPager`. */
export type UseDataGridUrlPaginationResult = {
  page: number;
  pageSize: number;
  /** The `pageSizeOptions` the URL parsing enforces (`pageSizeOptions` or the pager default) — `DataGridProvider` takes it, so the bar's select and the URL allow-list never diverge. */
  pageSizeOptions: readonly number[];
  onPageChange: (page: number) => void;
  /** `null` (a grid that turns paging off) returns the URL to `defaultPageSize`; the URL has no "every row" size. */
  onPageSizeChange: (pageSize: number | null) => void;
};

/**
 * Syncs `page`/`pageSize` with the URL via nuqs, with no dependency on the grid's store (it
 * reads only the page math of `data-grid-pagination`) — it owns two URL-backed numbers and hands back the controlled pair that
 * `DataGridProvider` and `useDataGridServerPager` both accept.
 *
 * The hook bounds the URL values but not the page range: the pager that knows the row count clamps an
 * out-of-range `page` and reports it through `onPageChange`.
 *
 * `page` is 1-based and omitted from the URL at 1; `pageSize` is omitted when it equals
 * `defaultPageSize`. Both writes use `history: "replace"`, matching this add-on's sort/filter/
 * search params — paging through results never pollutes back/forward history. Invalid or
 * out-of-range URL values (negative, fractional, a `pageSize` outside `pageSizeOptions`) clamp to
 * the default rather than throwing, the same posture as this add-on's other parsers.
 *
 * @example
 * const url = useDataGridUrlPagination();
 * <DataGridProvider data={rows} {...url}><DataGridPaginationBar /></DataGridProvider>
 */
export function useDataGridUrlPagination(options: UseDataGridUrlPaginationOptions = {}): UseDataGridUrlPaginationResult {
  const { prefix, pageSizeOptions } = options;
  useWarnSharedPrefix("useDataGridUrlPagination", prefix);
  const resolvedPageSizeOptions: readonly number[] = pageSizeOptions ?? DEFAULT_PAGE_SIZES;
  const defaultPageSize = options.defaultPageSize ?? resolvedPageSizeOptions[0]!;

  const [pageParam, setPageParam] = useQueryState(prefixedKey(prefix, "page"), {
    defaultValue: "",
    parse: (v) => v,
    serialize: (v) => v,
    history: "replace",
  });
  const [pageSizeParam, setPageSizeParam] = useQueryState(prefixedKey(prefix, "pageSize"), {
    defaultValue: "",
    parse: (v) => v,
    serialize: (v) => v,
    history: "replace",
  });

  // the URL value is always gated by a size list, so ?pageSize=100000000 can never force an unbounded fetch
  const page = parsePage(pageParam);
  const pageSize = parsePageSize(pageSizeParam, defaultPageSize, resolvedPageSizeOptions);
  const onPageChange = useCallback(
    (next: number) => {
      void setPageParam(serializePage(next) || null);
    },
    [setPageParam],
  );

  const onPageSizeChange = useCallback(
    (next: number | null) => {
      void setPageSizeParam(next === null ? null : serializePageSize(next, defaultPageSize) || null);
      // A page number is only valid for the size it was chosen at: a page-size change resets the page to 1 (the URL composition's contract).
      void setPageParam(null);
    },
    [setPageSizeParam, setPageParam, defaultPageSize],
  );

  return useMemo(
    () => ({ page, pageSize, pageSizeOptions: resolvedPageSizeOptions, onPageChange, onPageSizeChange }),
    [page, pageSize, resolvedPageSizeOptions, onPageChange, onPageSizeChange],
  );
}

"use client";

import { useCallback, useEffect, useLayoutEffect, useRef } from "react";
import { useQueryState } from "nuqs";
import {
  useDataGridActions,
  useDataGridAllColumns,
  useDataGridFilterState,
  useDataGridSearchText,
  useDataGridSortState,
} from "@/registry/default/components/data-grid/data-grid";
import { MAX_SPEC_SEARCH_LENGTH, isDev, pruneFilterSpecs, requestedGroupByOf, resolveCustomFilterOperators, setFilterListBound, setFilterValuesOf, useDataGridSelector, useDataGridStoreApi } from "@/registry/default/components/data-grid/data-grid-sdk";
import type { ColumnLayout, FilterOperatorInput } from "@/registry/default/components/data-grid/data-grid";
import { serializeSortState, parseSortState } from "./sort-param";
import { serializeGroupBy, parseGroupBy } from "./group-param";
import { parseLayoutPart, serializeLayoutPart, type UrlLayoutPart } from "./layout-param";
import { serializeFilterState, parseFilterState } from "./filter-param";
import { parseLegacyJoin } from "./join-param";
import { prefixedKey, useWarnSharedPrefix } from "./prefixed-key";

type UrlSpecPart = "sort" | "filter" | "search" | "group";

type UrlParams = Record<"sort" | "group" | "filter" | "join" | "q" | UrlLayoutPart, string>;

// Filter values and search text can hold personal data; a URL leaks them into history, logs, and Referer, so they sync only on request.
const DEFAULT_SPEC_PARTS: readonly UrlSpecPart[] = ["sort", "group"];

function choiceBoundsOf(columns: readonly { id: string; options?: unknown }[], state: Parameters<typeof setFilterListBound>[0]): Map<string, number | undefined> {
  return new Map(columns.map((c) => [c.id, setFilterListBound(state, c)]));
}

const DEFAULT_LAYOUT_PARTS: readonly UrlLayoutPart[] = ["order", "hidden"];

const LAYOUT_KEYS: Record<UrlLayoutPart, string> = { order: "cols", hidden: "hide", widths: "widths", pins: "pins" };

function readUrlParams(prefix: string | undefined): UrlParams {
  const query = new URLSearchParams(window.location.search);
  const read = (key: string) => query.get(prefixedKey(prefix, key)) ?? "";
  return { sort: read("sort"), group: read("group"), filter: read("filter"), join: read("join"), q: read("q"), order: read(LAYOUT_KEYS.order), hidden: read(LAYOUT_KEYS.hidden), widths: read(LAYOUT_KEYS.widths), pins: read(LAYOUT_KEYS.pins) };
}

function countUnknownLayoutIds(part: Partial<ColumnLayout>, known: ReadonlySet<string>): number {
  const ids = part.order ?? part.hidden ?? Object.keys(part.widths ?? part.pins ?? {});
  return ids.filter((id) => !known.has(id)).length;
}

/** Dev-only warning, core's `warnDev` pattern with this add-on's own prefix (import-boundary rule: add-ons import only from core's block-root barrel). */
function warnDev(message: string): void {
  if (isDev()) console.warn(`[data-grid-url-state] ${message}`);
}

/** Options for {@link useDataGridUrlState}. */
export type UseDataGridUrlStateOptions = {
  /** Namespaces the `sort`/`group`/`filter`/`join`/`q` URL keys and the layout keys (`cols`, `hide`, `widths`, `pins`) as `<prefix>_<key>`, so multiple grids can coexist on one page. */
  prefix?: string;
  /**
   * View-spec parts synced to the URL: `sort` (`sort`), `group` (`group`: the `groupBy` columns; expanded groups stay out), `filter` (`filter` and the top-level `join`), and `search` (`q`).
   * `[]` turns spec sync off. Default `["sort", "group"]`: filter values and search text reach the URL, browser history, server logs, and `Referer` only when you list `"filter"` and `"search"`.
   */
  spec?: readonly UrlSpecPart[];
  /**
   * Layout parts synced to the URL under `cols` (`order`), `hide` (`hidden`), `widths`, and `pins`.
   * A part is written only while it differs from the layout the grid started with. `[]` turns
   * layout sync off. Default `["order", "hidden"]`.
   */
  layout?: readonly UrlLayoutPart[];
  /**
   * Applies the URL to the grid when the user navigates back or forward (`popstate`), as `applyFromUrl()` does.
   * Set `false` to apply the URL yourself. Default `true`.
   */
  enableNavigationSync?: boolean;
};

/** Result of {@link useDataGridUrlState}. */
export type UseDataGridUrlStateResult = {
  /**
   * Re-applies the current URL params to the store, including the dropped-column warning. Unlike
   * the mount apply, a param missing from the URL clears its sort, filter, or search, and a
   * missing layout param resets that synced layout part to the layout the grid started with. Call
   * it when the URL changed outside the grid's own writes —
   * back/forward, a framework `setSearchParams`, or a query-only route change — since mount
   * applies exactly once and the store is the source of truth afterwards. Back and forward call it
   * already unless `enableNavigationSync` is `false`.
   */
  applyFromUrl: () => void;
};

/**
 * Syncs the grid store's `sortState`/`filterState`/`searchText` with the URL via
 * nuqs: applies any URL params to the store once on mount, then writes store changes back to the
 * URL (replacing, never pushing, history entries). Requires a `NuqsAdapter` (or the testing
 * adapter) above it in the tree — nuqs itself is router-agnostic. Writes are not delayed: the search
 * input debounces typing and nuqs coalesces the `history.replaceState` calls. A filter group lives inside the `filter` param. The join of the top-level
 * list is the `join` param: `join=or` when the list joins with "or", absent for "and".
 *
 * The URL→store direction runs on mount and on back/forward (`enableNavigationSync`); otherwise the store
 * wins. `applyFromUrl()` re-runs the apply when the URL changed outside the grid's own writes.
 */
export function useDataGridUrlState(options: UseDataGridUrlStateOptions = {}): UseDataGridUrlStateResult {
  const { prefix, layout = DEFAULT_LAYOUT_PARTS, spec: specParts = DEFAULT_SPEC_PARTS, enableNavigationSync = true } = options;
  const syncSort = specParts.includes("sort");
  const syncGroup = specParts.includes("group");
  const syncFilter = specParts.includes("filter");
  const syncSearch = specParts.includes("search");
  useWarnSharedPrefix("useDataGridUrlState", prefix);
  const layoutParts = layout.join(",");
  const actions = useDataGridActions();
  const storeApi = useDataGridStoreApi();
  const allColumns = useDataGridAllColumns();
  const warnedChoiceColumns = useRef(new Set<string>());
  const operatorInput = useCallback(
    (columnId: string, operator: string): FilterOperatorInput | undefined => {
      const column = allColumns.find((c) => c.id === columnId);
      if (!column) return undefined;
      const custom = resolveCustomFilterOperators(column, column.type ? storeApi.getState().cellTypes[column.type] : undefined).get(operator);
      return custom && (custom.input ?? "single");
    },
    [allColumns, storeApi],
  );
  const sortState = useDataGridSortState();
  const groupBy = useDataGridSelector(requestedGroupByOf);
  const filterState = useDataGridFilterState();
  const filterJoin = useDataGridSelector((s) => s.filterJoin);
  const searchText = useDataGridSearchText();
  const columnLayout = useDataGridSelector((s) => s.columnLayout);

  const [sortParam, setSortParam] = useQueryState(prefixedKey(prefix, "sort"), {
    defaultValue: "",
    parse: (v) => v,
    serialize: (v) => v,
    history: "replace",
  });
  const [groupParam, setGroupParam] = useQueryState(prefixedKey(prefix, "group"), {
    defaultValue: "",
    parse: (v) => v,
    serialize: (v) => v,
    history: "replace",
  });
  const [filterParam, setFilterParam] = useQueryState(prefixedKey(prefix, "filter"), {
    defaultValue: "",
    parse: (v) => v,
    serialize: (v) => v,
    history: "replace",
  });
  const [joinParam, setJoinParam] = useQueryState(prefixedKey(prefix, "join"), {
    defaultValue: "",
    parse: (v) => v,
    serialize: (v) => v,
    history: "replace",
  });
  const [searchParam, setSearchParam] = useQueryState(prefixedKey(prefix, "q"), {
    defaultValue: "",
    parse: (v) => v,
    serialize: (v) => v,
    history: "replace",
  });
  const layoutQueryOptions = { defaultValue: "", parse: (v: string) => v, serialize: (v: string) => v, history: "replace" } as const;
  const [orderParam, setOrderParam] = useQueryState(prefixedKey(prefix, LAYOUT_KEYS.order), layoutQueryOptions);
  const [hiddenParam, setHiddenParam] = useQueryState(prefixedKey(prefix, LAYOUT_KEYS.hidden), layoutQueryOptions);
  const [widthsParam, setWidthsParam] = useQueryState(prefixedKey(prefix, LAYOUT_KEYS.widths), layoutQueryOptions);
  const [pinsParam, setPinsParam] = useQueryState(prefixedKey(prefix, LAYOUT_KEYS.pins), layoutQueryOptions);
  const currentParams: UrlParams = { sort: sortParam, group: groupParam, filter: filterParam, join: joinParam, q: searchParam, order: orderParam, hidden: hiddenParam, widths: widthsParam, pins: pinsParam };

  // The nuqs setters are NOT stable across external URL changes (back/forward, setSearchParams,
  // the testing adapter's searchParams prop) — the adapter re-renders and the query hook rebuilds
  // its updater. They must stay out of the write-back effects' dep lists, or an external URL change
  // re-triggers the write-back and stomps the new URL value before applyFromUrl can read it. The
  // refs keep a live handle to the latest setter so the effects only re-run when the STORE state
  // (the actual source of truth) changes.
  const setSortParamRef = useRef(setSortParam);
  const setGroupParamRef = useRef(setGroupParam);
  const setFilterParamRef = useRef(setFilterParam);
  const setJoinParamRef = useRef(setJoinParam);
  const setSearchParamRef = useRef(setSearchParam);
  const layoutSettersRef = useRef({ order: setOrderParam, hidden: setHiddenParam, widths: setWidthsParam, pins: setPinsParam });
  // The query of the last popstate or of the last write: a popstate with the same query (a hash-only navigation) changes nothing.
  const seenSearchRef = useRef<string | null>(null);
  const noteWrite = (written: Promise<unknown>) => void written.then(() => (seenSearchRef.current = window.location.search), () => {});

  // Reads the current URL params and applies them to the store. Runs once on mount (via the
  // appliedRef guard below) and is exposed as applyFromUrl so a consumer can re-apply after an
  // external URL change (back/forward, setSearchParams, query-only route change).
  const applyUrl = useCallback((keepMountDefaults: boolean, params: UrlParams) => {
    const initialLayout = storeApi.getInitialState().columnLayout;
    const knownIds = new Set(allColumns.map((c) => c.id));
    const layoutPatch: Partial<ColumnLayout> = {};
    let unknownLayoutIds = 0;
    for (const part of layoutParts ? (layoutParts.split(",") as UrlLayoutPart[]) : []) {
      const parsed = parseLayoutPart(part, params[part]);
      if (parsed[part] !== undefined) {
        unknownLayoutIds += countUnknownLayoutIds(parsed, knownIds);
        Object.assign(layoutPatch, parsed);
      } else if (!keepMountDefaults) {
        Object.assign(layoutPatch, { [part]: initialLayout[part] });
      }
    }
    if (unknownLayoutIds > 0) warnDev(`dropped ${unknownLayoutIds} URL layout entries for removed columns`);
    // Drop specs a shared link must not apply: a removed column, or one the integrator excluded from sorting/filtering or currently hides. Each drop dev-warns.
    const hidden = new Set(layoutPatch.hidden ?? storeApi.getState().hiddenColumns);
    const usable = (c: (typeof allColumns)[number]) => !hidden.has(c.id);
    const sortableIds = new Set(allColumns.filter((c) => usable(c) && c.sortable !== false).map((c) => c.id));
    const filterableIds = new Set(allColumns.filter((c) => usable(c) && c.filterable !== false).map((c) => c.id));
    const parsedSorts = parseSortState(params.sort);
    const sorts = parsedSorts.filter((spec) => {
      if (sortableIds.has(spec.columnId)) return true;
      warnDev(`dropped URL sort spec for removed, hidden, or unsortable column "${spec.columnId}"`);
      return false;
    });
    const groupableIds = new Set(allColumns.filter((c) => usable(c) && c.groupable !== false).map((c) => c.id));
    const groups = parseGroupBy(params.group).filter((id) => {
      if (groupableIds.has(id)) return true;
      warnDev(`dropped URL group for removed, hidden, or ungroupable column "${id}"`);
      return false;
    });
    const choiceBounds = choiceBoundsOf(allColumns, storeApi.getState());
    const unknownChoices = new Map<string, number>();
    const parsedFilters = parseFilterState(params.filter, {
      maxChoices: (columnId) => choiceBounds.get(columnId),
      operatorInput,
      choiceValues: setFilterValuesOf(storeApi.getState()),
      onUnknownChoices: (columnId, count) => unknownChoices.set(columnId, (unknownChoices.get(columnId) ?? 0) + count),
    });
    for (const [columnId, count] of unknownChoices) {
      if (warnedChoiceColumns.current.has(columnId)) continue;
      warnedChoiceColumns.current.add(columnId);
      warnDev(`dropped ${count} URL filter values outside the column choices and data values of "${columnId}"`);
    }
    const rootJoin = parseLegacyJoin(params.join);
    const filters = pruneFilterSpecs(parsedFilters, (spec) => {
      if (filterableIds.has(spec.columnId)) return true;
      warnDev(`dropped URL filter spec for removed, hidden, or unfilterable column "${spec.columnId}"`);
      return false;
    }, true);
    // On mount an absent param keeps the grid's initial state; a re-apply mirrors the URL, so a removed param clears its state.
    if (syncSort && (sorts.length > 0 || !keepMountDefaults)) actions.setSorts(sorts);
    if (syncGroup && storeApi.getState().groupingEnabled && (groups.length > 0 || !keepMountDefaults)) actions.setGroupBy(groups);
    if (syncFilter && (filters.length > 0 || rootJoin === "or" || !keepMountDefaults)) {
      actions.setFilters(filters);
      actions.setFilterJoin(rootJoin);
    }
    if (syncSearch && (params.q || !keepMountDefaults)) actions.setSearch(params.q.slice(0, MAX_SPEC_SEARCH_LENGTH));

    if (Object.keys(layoutPatch).length > 0) actions.setColumnLayout(layoutPatch);
  }, [actions, allColumns, operatorInput, storeApi, syncSort, syncGroup, syncFilter, syncSearch, layoutParts]);
  const applyUrlRef = useRef(applyUrl);
  const currentParamsRef = useRef(currentParams);
  useLayoutEffect(() => {
    setSortParamRef.current = setSortParam;
    setGroupParamRef.current = setGroupParam;
    setFilterParamRef.current = setFilterParam;
    setJoinParamRef.current = setJoinParam;
    setSearchParamRef.current = setSearchParam;
    layoutSettersRef.current = { order: setOrderParam, hidden: setHiddenParam, widths: setWidthsParam, pins: setPinsParam };
    applyUrlRef.current = applyUrl;
    currentParamsRef.current = currentParams;
  });
  const applyFromUrl = useCallback(() => applyUrlRef.current(false, currentParamsRef.current), []);

  // apply URL -> store exactly once on mount; afterwards the store is the source of truth and
  // this effect's own writes below must not be re-read back as if they were external URL edits.
  const appliedRef = useRef(false);
  useEffect(() => {
    if (appliedRef.current) return;
    appliedRef.current = true;
    applyUrl(true, currentParams);
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (!enableNavigationSync) return;
    if (seenSearchRef.current === null) seenSearchRef.current = window.location.search;
    const onPopState = () => {
      if (window.location.search === seenSearchRef.current) return;
      seenSearchRef.current = window.location.search;
      applyUrlRef.current(false, readUrlParams(prefix));
    };
    window.addEventListener("popstate", onPopState);
    return () => window.removeEventListener("popstate", onPopState);
  }, [enableNavigationSync, prefix]);

  useEffect(() => {
    if (!appliedRef.current || !syncSort) return;
    noteWrite(setSortParamRef.current(serializeSortState(sortState) || null));
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, [sortState]);

  useEffect(() => {
    if (!appliedRef.current || !syncGroup) return;
    noteWrite(setGroupParamRef.current(serializeGroupBy(groupBy) || null));
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, [groupBy]);

  useEffect(() => {
    if (!appliedRef.current || !syncFilter) return;
    const choiceBounds = choiceBoundsOf(allColumns, storeApi.getState());
    noteWrite(setFilterParamRef.current(serializeFilterState(filterState, { operatorInput, maxChoices: (columnId) => choiceBounds.get(columnId) }) || null));
    noteWrite(setJoinParamRef.current(filterJoin === "or" ? "or" : null));
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, [filterState, filterJoin]);

  const lastWrittenLayoutRef = useRef<Partial<Record<UrlLayoutPart, string>> | null>(null);
  useEffect(() => {
    if (!appliedRef.current) return;
    const initialLayout = storeApi.getInitialState().columnLayout;
    const previous = lastWrittenLayoutRef.current;
    const next: Partial<Record<UrlLayoutPart, string>> = {};
    for (const part of layoutParts ? (layoutParts.split(",") as UrlLayoutPart[]) : []) {
      const value = serializeLayoutPart(part, columnLayout);
      next[part] = value === serializeLayoutPart(part, initialLayout) ? "" : value;
      if (previous && part in previous && previous[part] !== next[part]) noteWrite(layoutSettersRef.current[part](next[part] || null));
    }
    lastWrittenLayoutRef.current = next;
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, [columnLayout, layoutParts]);

  // The search text is already debounced by the input; the adapter coalesces the writes, so none is waited for here.
  useEffect(() => {
    if (!appliedRef.current || !syncSearch) return;
    noteWrite(setSearchParamRef.current(searchText.slice(0, MAX_SPEC_SEARCH_LENGTH) || null));
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, [searchText]);

  return { applyFromUrl };
}
